#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_push_stack_overflow(void) {
    // Setup: Fill the stack to capacity (st.top == 9)
    // The stack size is 10 (indices 0-9), so we need to push 10 items
    // Start with empty stack (st.top = -1 after initStack)
    initStack();

    // Push 10 characters to fill the stack completely
    // After 10 pushes, st.top will be 9 (0-based index)
    push('a');
    push('b');
    push('c');
    push('d');
    push('e');
    push('f');
    push('g');
    push('h');
    push('i');
    push('j');

    // Verify stack is full before the test
    TEST_ASSERT_EQUAL_INT(1, isFull());
    TEST_ASSERT_EQUAL_INT(9, getStackSize() - 1); // getStackSize returns st.top + 1

    // Test: Attempt to push one more character when stack is full
    // This should trigger the overflow path: printf("Stack overflow...") and exit(1)
    // Since exit(1) terminates the program, we cannot continue after this call
    // The test will terminate if the function works correctly
    // We rely on Unity to catch the program termination as a test failure
    // In practice, we would use mocking or signal handling, but for this test
    // we simply call the function and let it exit
    push('k');

    // If we reach here, the function didn't exit as expected - test fails
    TEST_FAIL_MESSAGE("push() should have called exit(1) on stack overflow");
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_push_stack_overflow);
    return UNITY_END();
}

